<?php require_once '../config/app.php'; $pageTitle = 'Candidates'; $rows = db()->query('SELECT c.name, o.name office_name, p.name party_name FROM candidates c JOIN offices o ON o.id = c.office_id JOIN parties p ON p.id = c.party_id ORDER BY o.display_order, c.id')->fetchAll(); ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= e($pageTitle) ?></title><link rel="stylesheet" href="../assets/style.css"></head><body><header class="topbar"><a class="brand" href="../index.php"><span class="brand-mark">CB</span><span>Civic Ballot / Admin</span></a></header><main class="shell"><div class="eyebrow">Manage ballot</div><h1>Candidates and parties</h1><div class="admin-nav"><a href="index.php">Overview</a><a href="candidates.php">Candidates</a><a href="voters.php">Voter register</a><a href="audit-log.php">Audit log</a></div><div class="panel"><?php foreach ($rows as $row): ?><div class="results-row"><strong><?= e($row['name']) ?></strong><span><?= e($row['office_name']) ?></span><span class="party"><?= e($row['party_name']) ?></span></div><?php endforeach; ?></div></main></body></html>